import { Option } from 'models/Filters';

export const AUDIENCE_PLANNING_FILTER_PAGE_PREFIX =
  'consumer_audience-planning';

export const isAudiencePlanningFilterPageName = (pageName: string): boolean =>
  pageName.startsWith(AUDIENCE_PLANNING_FILTER_PAGE_PREFIX);

export const isBeerSegmentOption = (
  option: Pick<Option, 'value' | 'label'>,
): boolean => {
  const value = String(option.value ?? '').toLowerCase();
  const label = String(option.label ?? '').toLowerCase();

  return value === 'beer' || label === 'beer';
};

export const getAudiencePlanningSidebarSegmentOptions = (
  apiOptions: Option[] = [],
): Option[] =>
  apiOptions.map((option) => ({
    ...option,
    isDisabled: !isBeerSegmentOption(option),
  }));

export const getAudiencePlanningQuickFilterSegmentOptions = (
  apiOptions: Option[] = [],
): Option[] => apiOptions.filter(isBeerSegmentOption);
